package com.gymflow.product;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/v1/gyms/{gymId}/products")public class ProductController{private final ProductService service;public ProductController(ProductService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ProductResponse create(@PathVariable UUID gymId,@Valid @RequestBody ProductRequest r){return service.create(gymId,r);}@PutMapping("/{productId}") public ProductResponse update(@PathVariable UUID gymId,@PathVariable UUID productId,@Valid @RequestBody ProductRequest r){return service.update(gymId,productId,r);}@GetMapping("/{productId}/history") public List<ProductChangeResponse> history(@PathVariable UUID gymId,@PathVariable UUID productId){return service.history(gymId,productId);}@GetMapping public List<ProductResponse> findAll(@PathVariable UUID gymId){return service.findAll(gymId);}}
